class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        m = len(pattern)
        for i in range(len(s) - m + 1):
            bad = 0
            for j in range(m):
                if s[i + j] != pattern[j]:
                    bad += 1
                    if bad > 1: break
            if bad <= 1: return i
        return -1

