        int m = pattern.size();
        for (int i = 0; i + m <= (int)s.size(); i++) {
            int bad = 0;
            for (int j = 0; j < m; j++)
                if (s[i + j] != pattern[j] && ++bad > 1) break;
            if (bad <= 1) return i;
        }
        return -1;
    }
};

