class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        def zfun(t):
            n = len(t); z = [0] * n; l = r = 0
            for i in range(1, n):
                if i < r: z[i] = min(r - i, z[i - l])
                while i + z[i] < n and t[z[i]] == t[i + z[i]]: z[i] += 1
                if i + z[i] > r: l, r = i, i + z[i]
            return z
        m, n = len(pattern), len(s)
        z1 = zfun(pattern + '#' + s)
        z2 = zfun(pattern[::-1] + '#' + s[::-1])
        for i in range(n - m + 1):
            if z1[m + 1 + i] + z2[m + 1 + (n - m - i)] >= m - 1:
                return i
        return -1

