class Solution {
    private int[] zfun(String t) {
        int n = t.length(); int[] z = new int[n]; int l = 0, r = 0;
        for (int i = 1; i < n; i++) {
            if (i < r) z[i] = Math.min(r - i, z[i - l]);
            while (i + z[i] < n && t.charAt(z[i]) == t.charAt(i + z[i])) z[i]++;
            if (i + z[i] > r) { l = i; r = i + z[i]; }
        }
        return z;
    }
    public int minStartingIndex(String s, String pattern) {
        int m = pattern.length(), n = s.length();
        int[] z1 = zfun(pattern + "#" + s);
        StringBuilder pb = new StringBuilder(pattern).reverse();
        StringBuilder sb = new StringBuilder(s).reverse();
        int[] z2 = zfun(pb + "#" + sb);
        for (int i = 0; i + m <= n; i++)
            if (z1[m + 1 + i] + z2[m + 1 + (n - m - i)] >= m - 1) return i;
        return -1;
    }
}

