        const n = t.length, z = Array(n).fill(0); let l = 0, r = 0;
        for (let i = 1; i < n; i++) {
            if (i < r) z[i] = Math.min(r - i, z[i - l]);
            while (i + z[i] < n && t[z[i]] === t[i + z[i]]) z[i]++;
            if (i + z[i] > r) { l = i; r = i + z[i]; }
        }
        return z;
    };
    const m = pattern.length, n = s.length;
    const z1 = zfun(pattern + '#' + s);
    const z2 = zfun([...pattern].reverse().join('') + '#' + [...s].reverse().join(''));
    for (let i = 0; i + m <= n; i++)
        if (z1[m + 1 + i] + z2[m + 1 + (n - m - i)] >= m - 1) return i;
    return -1;
